import heapq

def shortest_path(edges, start, end):
    """
    Finds the shortest path between two nodes in a directed weighted graph.

    Args:
        edges (list): List of tuples (from_node, to_node, weight)
        start (str): Starting node
        end (str): Ending node

    Returns:
        tuple: (distance, path) if path exists, else (None, None)

    Raises:
        ValueError: If any edge has a negative weight
    """
    # Handle case where start and end are the same node
    if start == end:
        return (0, [start])

    # Build adjacency list and check for negative weights
    graph = {}
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")

        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Initialize distances and previous nodes dictionary
    all_nodes = set()
    for from_node in edges:
        all_nodes.add(from_node[0])
        all_nodes.add(from_node[1])

    distances = {node: float('inf') for node in all_nodes}
    previous = {}

    # Start with the starting node
    if start not in graph or end not in graph:
        return (None, None)

    distances[start] = 0
    pq = [(0, start)]  # Priority queue: (distance, node)

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        # Skip if we've already found a shorter path to this node
        if current_dist > distances[current_node]:
            continue

        # If we reached the destination, break early
        if current_node == end:
            break

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                distance = current_dist + weight

                # Relaxation step
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous[neighbor] = current_node
                    heapq.heappush(pq, (distance, neighbor))

    # Check if path exists
    if distances[end] == float('inf'):
        return (None, None)

    # Reconstruct path from end to start using the 'previous' dictionary
    path = []
    node = end
    while node != start:
        if node not in previous:
            return (None, None)  # This should not happen in a valid graph
        path.append(node)
        node = previous[node]
    path.append(start)

    path.reverse()

    return (distances[end], path)


# Test examples
if __name__ == "__main__":
    print("Test 1:", shortest_path([("A", "B", 1), ("B", "C", 2), ("A", "C", 5)], "A", "C"))
    # Expected: (3, ['A', 'B', 'C'])

    print("Test 2:", shortest_path([("A", "B", 1)], "A", "A"))
    # Expected: (0, ['A'])

    print("Test 3:", shortest_path([("A", "B", 1)], "A", "C"))
    # Expected: (None, None)

    try:
        print("Test 4:", shortest_path([("A", "B", -1)], "A", "B"))
    except ValueError as e:
        print("Test 4 caught ValueError:", str(e))
